from openmm.app import PDBFile
import openmm.unit as u, numpy as np
p=PDBFile('/tmp/capfix/fixed.pdb'); pos=p.positions.value_in_unit(u.angstrom)
rs=list(p.topology.residues())
print('nres',len(rs))
for i,r in enumerate(rs):
    if 17 <= int(r.id) <= 22 or r.name in ('NME','ACE'):
        print('ordinal',i+1,'id',r.id,r.insertionCode,r.name,[(a.name,np.round(pos[a.index],3).tolist()) for a in r.atoms() if a.element.symbol!='H'])
# Cap-region heavy contacts between residues around the gap.
for i in range(16,23):
    if i>=len(rs): break
    for j in range(i+1,23):
        if j>=len(rs): break
        for a in rs[i].atoms():
            if a.element.symbol=='H': continue
            for b in rs[j].atoms():
                if b.element.symbol=='H': continue
                d=np.linalg.norm(pos[a.index]-pos[b.index])
                if d<2.2: print('close',i+1,rs[i].id,rs[i].name,a.name,'--',j+1,rs[j].id,rs[j].name,b.name,round(float(d),3))
